//! The ported functions against what the Electron engine answered (`fixtures.json`, generated by `local/gen-engine-data.mjs`).

use engine::chords::{analyze_seed, default_name, is_valid_chord, parse_lines, transpose_chord};
use engine::slots::{parse_slots, resolve_style_spec, sanitize_pattern, serialize_slots};
use serde_json::Value;

fn fixtures() -> Value {
    serde_json::from_str(include_str!("fixtures.json")).unwrap()
}

#[test]
fn slots_round_trip() {
    for c in fixtures()["slots"].as_array().unwrap() {
        let text = c["in"].as_str().unwrap();
        assert_eq!(serialize_slots(&parse_slots(text)), c["out"].as_str().unwrap(), "{text}");
        assert_eq!(parse_slots(text).len(), c["parsed"].as_array().unwrap().len(), "{text}");
    }
}

#[test]
fn lines_and_default_names() {
    for c in fixtures()["lines"].as_array().unwrap() {
        let text = c["in"].as_str().unwrap();
        let got: Vec<Vec<(String, f64)>> = parse_lines(text).into_iter().map(|l| l.into_iter().map(|t| (t.sym, t.w)).collect()).collect();
        let want: Vec<Vec<(String, f64)>> = c["lines"]
            .as_array()
            .unwrap()
            .iter()
            .map(|l| l.as_array().unwrap().iter().map(|t| (t["sym"].as_str().unwrap().to_owned(), t["w"].as_f64().unwrap())).collect())
            .collect();
        assert_eq!(got, want, "{text}");
        for (i, n) in c["names"].as_array().unwrap().iter().enumerate() {
            let t = [0, 3, -5][i];
            assert_eq!(default_name(text, t), n.as_str().unwrap(), "{text} +{t}");
        }
    }
}

#[test]
fn transposes() {
    for c in fixtures()["transposes"].as_array().unwrap() {
        let sym = c["sym"].as_str().unwrap();
        let t = c["t"].as_i64().unwrap() as i32;
        assert_eq!(transpose_chord(sym, t), c["out"].as_str().unwrap(), "{sym} {t}");
    }
}

#[test]
fn chord_validity_matches_voicing() {
    for c in fixtures()["voices"].as_array().unwrap() {
        let sym = c["sym"].as_str().unwrap();
        assert_eq!(is_valid_chord(sym), c["v"] != "ERR", "{sym}");
    }
}

#[test]
fn analyze() {
    for c in fixtures()["analyze"].as_array().unwrap() {
        let r = &c["r"];
        let got = analyze_seed(c["p"].as_str().unwrap(), 93.0, c["bars"].as_f64().unwrap(), c["sig"].as_str().unwrap(), 3.0, c["format"] == "mp3", 256.0);
        assert_eq!(got.count as u64, r["count"].as_u64().unwrap());
        assert_eq!(got.invalid.len(), r["invalid"].as_array().unwrap().len());
        assert_eq!(got.sig_bad, r["sigBad"].as_bool().unwrap());
        assert!((got.seconds - r["seconds"].as_f64().unwrap()).abs() < 1e-9, "{} {}", c["p"], c["sig"]);
        assert!((got.audio_bytes - r["audioBytes"].as_f64().unwrap()).abs() < 0.5);
    }
}

#[test]
fn resolve_specs() {
    for c in fixtures()["resolve"].as_array().unwrap() {
        let i = &c["in"];
        let pattern = i.get("pattern").and_then(Value::as_object);
        let got = resolve_style_spec(
            i.get("style").and_then(Value::as_str).unwrap_or("pad"),
            i.get("chordFigure").and_then(Value::as_str).unwrap_or(""),
            i.get("bassFigure").and_then(Value::as_str).unwrap_or(""),
            pattern,
        );
        let want = c["out"].as_object().unwrap();
        for (k, v) in want {
            if k.ends_with("Lane") {
                for (lk, lv) in v.as_object().unwrap() {
                    let g = &got[k][lk];
                    assert!(g == lv || g.as_f64() == lv.as_f64(), "{i} {k}.{lk}");
                }
            } else if k != "group" {
                assert_eq!(&got[k], v, "{i} {k}");
            }
        }
    }
}

#[test]
fn sanitize() {
    for c in fixtures()["sanitize"].as_array().unwrap() {
        let got = sanitize_pattern(&c["in"]).map(Value::Object).unwrap_or(Value::Null);
        assert_eq!(got, c["out"], "{}", c["in"]);
    }
}
